      "heading": "🎭 Spelarspotlight",
      "mascotIntro1": "Låt oss se vilka spelare vi har!",
      "mascotIntro2": "Varje spelare har en historia. Här är din!",
      "mascotIntro3": "Dags att möta karaktärerna!",
